import { getUserLogoDesignProjects } from '@/lib/api/client-api';
import { format } from 'date-fns';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { PlusIcon, ChevronRightIcon, PaintbrushIcon, CalendarIcon, BriefcaseIcon } from 'lucide-react';

type LogoDesignProject = {
  id: string;
  title: string;
  description: string | null;
  status: string;
  industry?: string;
  color_preferences?: string;
  style_preferences?: string;
  is_placeholder?: boolean;
  created_at: string;
  updated_at: string;
};

export default function LogoDesignProjectsPage() {
  const { user, isLoading: authLoading } = useAuth();
  const [projects, setProjects] = useState<LogoDesignProject[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadProjects = async () => {
      try {
        setIsLoading(true);
        setError(null);

        const projectsData = await getUserLogoDesignProjects();
        // console.log('Logo Design Projects:', projectsData);

        // Filter out placeholder projects or handle them specially
        const activeProjects = projectsData.filter(project => !project.is_placeholder);
        setProjects(activeProjects);

        // Check if we only have placeholder projects
        if (projectsData.length > 0 && activeProjects.length === 0) {
          // We only have placeholder projects - all projects are placeholders
          setProjects(projectsData);
        }
      } catch (err: any) {
        // console.error('Error loading logo design projects:', err);
        setError(err.message || "Failed to load projects");
        setProjects([]);
      } finally {
        setIsLoading(false);
      }
    };

    if (!authLoading && user) {
      loadProjects();
    }
  }, [authLoading, user]);

  const getStatusBadge = (status: string) => {
    let variant = 'default';
    let label = status.replace(/_/g, ' ');

    switch(status.toLowerCase()) {
      case 'in_progress':
      case 'in-progress':
        variant = 'secondary';
        label = 'In Progress';
        break;
      case 'completed':
        variant = 'success';
        label = 'Completed';
        break;
      case 'pending':
        variant = 'outline';
        label = 'Pending';
        break;
      case 'not-started':
      case 'not_started':
        variant = 'outline';
        label = 'Not Started';
        break;
      case 'cancelled':
        variant = 'destructive';
        label = 'Cancelled';
        break;
    }

    return (
      <Badge variant={variant as "default" | "secondary" | "outline" | "destructive"}>{label}</Badge>
    );
  };

  // Loading state
  if (authLoading || isLoading) {
    return (
      <div className="container mx-auto py-6 space-y-6">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold">Logo Design Projects</h1>
        </div>
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3].map((i) => (
            <Card key={i} className="overflow-hidden">
              <CardHeader className="p-4 pb-2">
                <Skeleton className="h-5 w-3/4 mb-2" />
                <Skeleton className="h-4 w-1/2" />
              </CardHeader>
              <CardContent className="p-4 pt-2">
                <Skeleton className="h-4 w-full mb-2" />
                <Skeleton className="h-4 w-3/4" />
              </CardContent>
              <div className="p-4 flex justify-between items-center">
                <Skeleton className="h-4 w-1/3" />
                <Skeleton className="h-8 w-20 rounded-md" />
              </div>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="container mx-auto py-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold">Logo Design Projects</h1>
        </div>
        <Card className="text-center p-8">
          <CardContent className="pt-6">
            <p className="text-red-500 mb-4">{error}</p>
            <Button onClick={() => window.location.reload()}>
              Try Again
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Empty state or only placeholder projects
  if (projects.length === 0 || (projects.length > 0 && projects.every(p => p.is_placeholder))) {
    return (
      <div className="container mx-auto py-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold">Logo Design Projects</h1>
        </div>
        <Card className="text-center p-8">
          <CardContent className="pt-6">
            <h3 className="text-xl font-semibold mb-4">No Active Logo Design Projects</h3>
            <p className="text-muted-foreground mb-6">
              You do not have any active logo design projects at the moment. Contact us to start a new logo design project.
            </p>
            <div className="flex justify-center">
              <Button asChild>
                <Link href="https://www.drasticdigital.com/contact" target="_blank" rel="noopener noreferrer">
                  Contact Us to Start a Project
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Projects display
  return (
    <div className="container mx-auto py-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Logo Design Projects</h1>
        <Button asChild>
          <Link href="https://www.drasticdigital.com/contact" target="_blank" rel="noopener noreferrer">
            <PlusIcon className="mr-2 h-4 w-4" />
            Request New Project
          </Link>
        </Button>
      </div>

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {projects.map((project) => (
          <Card key={project.id} className="overflow-hidden">
            <CardHeader className="p-4 pb-2">
              <div className="flex justify-between items-start">
                <CardTitle className="text-xl">{project.title || 'Untitled Project'}</CardTitle>
                {getStatusBadge(project.status)}
              </div>
              <CardDescription>
                Logo Design
              </CardDescription>
            </CardHeader>
            <CardContent className="p-4 pt-2">
              <p className="text-sm text-muted-foreground line-clamp-2">
                {project.description || 'No description provided.'}
              </p>

              <div className="mt-4 space-y-2">
                {project.industry && (
                  <div className="flex items-center text-sm">
                    <BriefcaseIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                    <span>Industry: {project.industry.replace(/_/g, ' ')}</span>
                  </div>
                )}
                {project.color_preferences && (
                  <div className="flex items-center text-sm">
                    <PaintbrushIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                    <span>Colors: {project.color_preferences}</span>
                  </div>
                )}
                <div className="flex items-center text-sm">
                  <CalendarIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                  <span>Updated: {format(new Date(project.updated_at), 'MMM d, yyyy')}</span>
                </div>
              </div>
            </CardContent>
            <div className="p-4 flex justify-between items-center">
              {project.is_placeholder ? (
                <Button variant="secondary" disabled>
                  Coming Soon
                </Button>
              ) : (
                <Button asChild variant="default">
                  <Link href={`/client/projects/logo-design/${project.id}`}>
                    View Details
                    <ChevronRightIcon className="ml-2 h-4 w-4" />
                  </Link>
                </Button>
              )}
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { useAuth } from '../../../../features/auth';
import { Card } from '../../../../shared/ui/molecules';
import { 
  getClientProjectsForCategories, 
  ProjectCategoryCounts 
} from '../../../../lib/api/client-api';
import { ProjectType } from '@/lib/types/project';

export default function ProjectsPage() {
  const { isAuthenticated, isLoading: authIsLoading, user } = useAuth();
  const router = useRouter();

  const [projectInfo, setProjectInfo] = useState<ProjectCategoryCounts>({});
  const [projectsLoading, setProjectsLoading] = useState<boolean>(true);

  // Project categories with descriptions and links
  const projectCategories: { id: ProjectType; slug: string; name: string; description: string; icon: JSX.Element; }[] = [
    {
      id: 'web_design',
      slug: 'web-design',
      name: 'Web Design',
      description: 'Responsive websites tailored to your brand and audience',
      icon: (
        <svg className="w-8 h-8 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"></path>
        </svg>
      )
    },
    {
      id: 'logo_design',
      slug: 'logo-design',
      name: 'Logo Design',
      description: 'Professional logo designs to represent your brand identity',
      icon: (
        <svg className="w-8 h-8 text-purple-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01"></path>
        </svg>
      )
    },
    {
      id: 'social_graphics',
      slug: 'social-graphics',
      name: 'Social Graphics',
      description: 'Eye-catching graphics for your social media platforms',
      icon: (
        <svg className="w-8 h-8 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"></path>
        </svg>
      )
    }
  ];

  useEffect(() => {
    if (!authIsLoading && !isAuthenticated) {
      router.push('/login');
    }
  }, [authIsLoading, isAuthenticated, router]);

  useEffect(() => {
    if (isAuthenticated && user) {
      const fetchProjectData = async () => {
        setProjectsLoading(true);
        try {
          const data = await getClientProjectsForCategories();
          setProjectInfo(data);
        } catch (error) {
          // console.error("Failed to fetch project counts:", error);
        } finally {
          setProjectsLoading(false);
        }
      };
      fetchProjectData();
    }
  }, [isAuthenticated, user]);

  // Show loading state while checking authentication or fetching projects
  if (authIsLoading || (isAuthenticated && projectsLoading)) {
    return (
      <div className="flex items-center justify-center min-h-[300px]">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-red-500"></div>
      </div>
    );
  }

  // Don't render if not authenticated
  if (!isAuthenticated) {
    return null;
  }

  return (
    <div className="p-6 bg-white dark:bg-black">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-12">
