          <p className="text-gray-600 dark:text-gray-400 max-w-xl mx-auto">
            Access your design projects and track their progress. Choose a project category below to view your active projects.
          </p>
        </div>

        {/* Project categories */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {projectCategories.map((category) => {
            const categoryProjectInfo = projectInfo[category.id];
            const count = categoryProjectInfo?.count || 0;
            const singleProjectId = categoryProjectInfo?.singleProjectId;

            let href = `/client/projects/${category.slug}`;
            let linkText = "View Projects";

            if (count === 1 && singleProjectId) {
              href = `/client/projects/${category.slug}/${singleProjectId}`;
              linkText = "View Project";
            }

            return (
              <Link href={projectsLoading ? '#' : href} key={category.id} passHref legacyBehavior={projectsLoading ? true : undefined}>
                <a className={`${projectsLoading ? 'pointer-events-none opacity-50' : ''}`}>
                  <Card className="h-full bg-white dark:bg-black shadow-lg hover:shadow-xl transition-shadow border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden hover:border-blue-500 dark:hover:border-blue-500 cursor-pointer">
                    <div className="p-6 flex flex-col h-full">
                      <div className="mb-4">
                        {category.icon}
                      </div>
                      <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">{category.name}</h3>
                      <p className="text-gray-600 dark:text-gray-400 text-sm flex-grow">{category.description}</p>
                      <div className="mt-6">
                        <span className="text-blue-600 dark:text-blue-400 flex items-center text-sm font-medium">
                          {projectsLoading ? 'Loading...' : linkText}
                          {!projectsLoading && (
                            <svg className="w-4 h-4 ml-1" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path>
                            </svg>
                          )}
                        </span>
                      </div>
                    </div>
                  </Card>
                </a>
              </Link>
            );
          })}
        </div>

        {/* Support section */}
        <div className="mt-16 bg-gray-50 dark:bg-gray-800 rounded-xl p-6 text-center">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">Need help or want to start a new project?</h3>
          <p className="text-gray-600 dark:text-gray-400 mb-4">
            Contact our support team to discuss your requirements or request a new design project.
          </p>
          <a
            href="https://www.drasticdigital.com/contact"
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center justify-center px-6 py-3 border border-transparent text-base font-medium rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 dark:bg-blue-500 dark:hover:bg-blue-600 dark:focus:ring-offset-gray-800"
          >
            Contact Support
          </a>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { useAuth } from '@/features/auth';
import { getUserSocialGraphicsProjects } from '@/lib/api/client-api';
import { format } from 'date-fns';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { PlusIcon, ChevronRightIcon, LayoutIcon, CalendarIcon, HashIcon } from 'lucide-react';

type SocialGraphicsProject = {
  id: string;
  title: string;
  description: string | null;
  status: string;
  social_platform?: string;
  content_type?: string;
  dimensions?: string;
  is_placeholder?: boolean;
  created_at: string;
  updated_at: string;
};

export default function SocialGraphicsProjectsPage() {
  const { user, isLoading: authLoading } = useAuth();
  const [projects, setProjects] = useState<SocialGraphicsProject[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadProjects = async () => {
      try {
        setIsLoading(true);
        setError(null);

        const projectsData = await getUserSocialGraphicsProjects();
        // console.log('Social Graphics Projects:', projectsData);

        // Filter out placeholder projects or handle them specially
        const activeProjects = projectsData.filter(project => !project.is_placeholder);
        setProjects(activeProjects);

        // Check if we only have placeholder projects
        if (projectsData.length > 0 && activeProjects.length === 0) {
          // We only have placeholder projects - all projects are placeholders
          setProjects(projectsData);
        }
      } catch (err: any) {
        // console.error('Error loading social graphics projects:', err);
        setError(err.message || "Failed to load projects");
        setProjects([]);
      } finally {
        setIsLoading(false);
      }
    };

    if (!authLoading && user) {
      loadProjects();
    }
  }, [authLoading, user]);

  const getStatusBadge = (status: string) => {
    let variant = 'default';
    let label = status.replace(/_/g, ' ');

    switch(status.toLowerCase()) {
      case 'in_progress':
      case 'in-progress':
        variant = 'secondary';
        label = 'In Progress';
        break;
      case 'completed':
        variant = 'success';
        label = 'Completed';
        break;
      case 'pending':
        variant = 'outline';
        label = 'Pending';
        break;
      case 'not-started':
      case 'not_started':
        variant = 'outline';
        label = 'Not Started';
        break;
      case 'cancelled':
        variant = 'destructive';
        label = 'Cancelled';
        break;
    }

    return (
      <Badge variant={variant as "default" | "secondary" | "outline" | "destructive"}>{label}</Badge>
    );
  };

  const getPlatformLabel = (platform?: string) => {
    if (!platform) return 'Social Graphics';

    const platformName = platform.replace(/_/g, ' ');
    return platformName.charAt(0).toUpperCase() + platformName.slice(1);
  };

  // Loading state
  if (authLoading || isLoading) {
    return (
      <div className="container mx-auto py-6 space-y-6">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold">Social Graphics Projects</h1>
        </div>
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3].map((i) => (
            <Card key={i} className="overflow-hidden">
              <CardHeader className="p-4 pb-2">
                <Skeleton className="h-5 w-3/4 mb-2" />
                <Skeleton className="h-4 w-1/2" />
              </CardHeader>
              <CardContent className="p-4 pt-2">
                <Skeleton className="h-4 w-full mb-2" />
                <Skeleton className="h-4 w-3/4" />
              </CardContent>
              <div className="p-4 flex justify-between items-center">
                <Skeleton className="h-4 w-1/3" />
                <Skeleton className="h-8 w-20 rounded-md" />
              </div>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="container mx-auto py-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold">Social Graphics Projects</h1>
        </div>
        <Card className="text-center p-8">
          <CardContent className="pt-6">
            <p className="text-red-500 mb-4">{error}</p>
            <Button onClick={() => window.location.reload()}>
              Try Again
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Empty state or only placeholder projects
  if (projects.length === 0 || (projects.length > 0 && projects.every(p => p.is_placeholder))) {
    return (
      <div className="container mx-auto py-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold">Social Graphics Projects</h1>
        </div>
        <Card className="text-center p-8">
          <CardContent className="pt-6">
            <h3 className="text-xl font-semibold mb-4">No Active Social Graphics Projects</h3>
            <p className="text-muted-foreground mb-6">
              You do not have any active social graphics projects at the moment. Contact us to start a new social media graphics project.
            </p>
            <div className="flex justify-center">
              <Button asChild>
                <Link href="https://www.drasticdigital.com/contact" target="_blank" rel="noopener noreferrer">
                  Contact Us to Start a Project
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Projects display
  return (
    <div className="container mx-auto py-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Social Graphics Projects</h1>
        <Button asChild>
          <Link href="https://www.drasticdigital.com/contact" target="_blank" rel="noopener noreferrer">
            <PlusIcon className="mr-2 h-4 w-4" />
            Request New Project
          </Link>
        </Button>
      </div>

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {projects.map((project) => (
          <Card key={project.id} className="overflow-hidden">
            <CardHeader className="p-4 pb-2">
              <div className="flex justify-between items-start">
                <CardTitle className="text-xl">{project.title || 'Untitled Project'}</CardTitle>
                {getStatusBadge(project.status)}
              </div>
              <CardDescription>
                {getPlatformLabel(project.social_platform)}
              </CardDescription>
            </CardHeader>
            <CardContent className="p-4 pt-2">
              <p className="text-sm text-muted-foreground line-clamp-2">
                {project.description || 'No description provided.'}
              </p>

              <div className="mt-4 space-y-2">
                {project.content_type && (
                  <div className="flex items-center text-sm">
                    <LayoutIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                    <span>Type: {project.content_type.replace(/_/g, ' ')}</span>
                  </div>
                )}
                {project.dimensions && (
                  <div className="flex items-center text-sm">
                    <HashIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                    <span>Size: {project.dimensions}</span>
                  </div>
                )}
                <div className="flex items-center text-sm">
                  <CalendarIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                  <span>Updated: {format(new Date(project.updated_at), 'MMM d, yyyy')}</span>
                </div>
              </div>
            </CardContent>
            <div className="p-4 flex justify-between items-center">
              {project.is_placeholder ? (
                <Button variant="secondary" disabled>
                  Coming Soon
                </Button>
              ) : (
                <Button asChild variant="default">
                  <Link href={`/client/projects/social-graphics/${project.id}`}>
                    View Details
                    <ChevronRightIcon className="ml-2 h-4 w-4" />
                  </Link>
                </Button>
              )}
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

