'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { useAuth } from '@/features/auth';
import { getUserWebDesignProjects } from '@/lib/api/client-api';
import { format } from 'date-fns';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { PlusIcon, ChevronRightIcon, GlobeIcon, CalendarIcon } from 'lucide-react';

type WebDesignProject = {
  id: string;
  title: string;
  description: string | null;
  status: string;
  website_type?: string;
  current_stage?: string;
  is_placeholder?: boolean;
  created_at: string;
  updated_at: string;
};

export default function WebDesignProjectsPage() {
  const { user, isLoading: authLoading } = useAuth();
  const [projects, setProjects] = useState<WebDesignProject[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadProjects = async () => {
      try {
        setIsLoading(true);
        setError(null);

        const projectsData = await getUserWebDesignProjects();
        // console.log('Web Design Projects:', projectsData);

        // Filter out placeholder projects or handle them specially
        const activeProjects = projectsData.filter(project => !project.is_placeholder);
        setProjects(activeProjects);

        // Check if we only have placeholder projects
        if (projectsData.length > 0 && activeProjects.length === 0) {
          // We only have placeholder projects - all projects are placeholders
          setProjects(projectsData);
        }
      } catch (err: any) {
        // console.error('Error loading web design projects:', err);
        setError(err.message || "Failed to load projects");
        setProjects([]);
      } finally {
        setIsLoading(false);
      }
    };

    if (!authLoading && user) {
      loadProjects();
    }
  }, [authLoading, user]);

  const getStatusBadge = (status: string) => {
    let variant = 'default';
    let label = status.replace(/_/g, ' ');

    switch(status.toLowerCase()) {
      case 'in_progress':
      case 'in-progress':
        variant = 'secondary';
        label = 'In Progress';
        break;
      case 'completed':
        variant = 'success';
        label = 'Completed';
        break;
      case 'pending':
        variant = 'outline';
        label = 'Pending';
        break;
      case 'not-started':
      case 'not_started':
        variant = 'outline';
        label = 'Not Started';
        break;
      case 'cancelled':
        variant = 'destructive';
        label = 'Cancelled';
        break;
    }

    return (
      <Badge variant={variant as "default" | "secondary" | "outline" | "destructive"}>{label}</Badge>
    );
  };

  // Loading state
  if (authLoading || isLoading) {
    return (
      <div className="container mx-auto py-6 space-y-6">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold">Web Design Projects</h1>
        </div>
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3].map((i) => (
            <Card key={i} className="overflow-hidden">
              <CardHeader className="p-4 pb-2">
                <Skeleton className="h-5 w-3/4 mb-2" />
                <Skeleton className="h-4 w-1/2" />
              </CardHeader>
              <CardContent className="p-4 pt-2">
                <Skeleton className="h-4 w-full mb-2" />
                <Skeleton className="h-4 w-3/4" />
              </CardContent>
              <div className="p-4 flex justify-between items-center">
                <Skeleton className="h-4 w-1/3" />
                <Skeleton className="h-8 w-20 rounded-md" />
              </div>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="container mx-auto py-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold">Web Design Projects</h1>
        </div>
        <Card className="text-center p-8">
          <CardContent className="pt-6">
            <p className="text-red-500 mb-4">{error}</p>
            <Button onClick={() => window.location.reload()}>
              Try Again
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Empty state or only placeholder projects
  if (projects.length === 0 || (projects.length > 0 && projects.every(p => p.is_placeholder))) {
    return (
      <div className="container mx-auto py-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold">Web Design Projects</h1>
        </div>
        <Card className="text-center p-8">
          <CardContent className="pt-6">
            <h3 className="text-xl font-semibold mb-4">No Active Web Design Projects</h3>
            <p className="text-muted-foreground mb-6">
              You do not have any active web design projects at the moment. Contact us to start a new website project.
            </p>
            <div className="flex justify-center">
              <Button asChild>
                <Link href="https://www.drasticdigital.com/contact" target="_blank" rel="noopener noreferrer">
                  Contact Us to Start a Project
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Projects display
  return (
    <div className="container mx-auto py-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Web Design Projects</h1>
        <Button asChild>
          <Link href="https://www.drasticdigital.com/contact" target="_blank" rel="noopener noreferrer">
            <PlusIcon className="mr-2 h-4 w-4" />
            Request New Project
          </Link>
        </Button>
      </div>

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {projects.map((project) => (
          <Card key={project.id} className="overflow-hidden">
            <CardHeader className="p-4 pb-2">
              <div className="flex justify-between items-start">
                <CardTitle className="text-xl">{project.title || 'Untitled Project'}</CardTitle>
                {getStatusBadge(project.status)}
              </div>
              <CardDescription>
                {project.website_type ? project.website_type.replace(/_/g, ' ') : 'Web Design'}
              </CardDescription>
            </CardHeader>
            <CardContent className="p-4 pt-2">
              <p className="text-sm text-muted-foreground line-clamp-2">
                {project.description || 'No description provided.'}
              </p>

              <div className="mt-4 space-y-2">
                {project.current_stage && (
                  <div className="flex items-center text-sm">
                    <GlobeIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                    <span>Current Stage: {project.current_stage.replace(/_/g, ' ')}</span>
                  </div>
                )}
                <div className="flex items-center text-sm">
                  <CalendarIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                  <span>Updated: {format(new Date(project.updated_at), 'MMM d, yyyy')}</span>
                </div>
              </div>
            </CardContent>
            <div className="p-4 flex justify-between items-center">
              {project.is_placeholder ? (
                <Button variant="secondary" disabled>
                  Coming Soon
                </Button>
              ) : (
                <Button asChild variant="default">
                  <Link href={`/client/projects/web-design/${project.id}`}>
                    View Details
                    <ChevronRightIcon className="ml-2 h-4 w-4" />
                  </Link>
                </Button>
              )}
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Calendar } from '@/components/ui/calendar';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { ArrowPathIcon } from '@heroicons/react/24/outline';
import { getUserProfile, getDesignerTasks } from '@/lib/api/client-api';
import { DesignerTask } from '@/lib/types/task';

export default function DesignerCalendarPage() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [tasks, setTasks] = useState<DesignerTask[]>([]);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(new Date());

  useEffect(() => {
    const loadCalendarData = async () => {
      try {
        setIsLoading(true);
        setError(null);

        // Get user profile
        const userProfile = await getUserProfile();

        // Check role
        if (userProfile?.role !== 'designer') {
          router.push('/dashboard');
          return;
        }

        // Fetch designer's tasks
        const designerTasks = await getDesignerTasks(userProfile.id);
        setTasks(designerTasks);
      } catch (err) {
        console.error('Error loading calendar data:', err);
        setError('Failed to load calendar data');
      } finally {
        setIsLoading(false);
      }
    };

    loadCalendarData();
  }, [router]);

  // Get tasks for selected date
  const getTasksForDate = (date: Date) => {
    return tasks.filter(task => {
      if (!task.due_date) return false;
      const taskDate = new Date(task.due_date);
      return taskDate.toDateString() === date.toDateString();
    });
  };

  // Get tasks for selected month
  const getTasksForMonth = (date: Date) => {
    return tasks.filter(task => {
      if (!task.due_date) return false;
      const taskDate = new Date(task.due_date);
      return taskDate.getMonth() === date.getMonth() && 
             taskDate.getFullYear() === date.getFullYear();
    });
  };

  // Get badge color based on task priority
  const getPriorityColor = (priority: string) => {
    switch(priority) {
      case 'high': return 'bg-red-100 text-red-800';
      case 'medium': return 'bg-yellow-100 text-yellow-800';
      case 'low': return 'bg-green-100 text-green-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <ArrowPathIcon className="h-8 w-8 text-gray-500 animate-spin" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-red-50 p-4 rounded-md">
          <p className="text-red-700">{error}</p>
        </div>
      </div>
    );
  }

  const selectedDateTasks = selectedDate ? getTasksForDate(selectedDate) : [];
  const monthTasks = selectedDate ? getTasksForMonth(selectedDate) : [];

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <h1 className="text-2xl font-bold text-gray-900 mb-8">Designer Calendar</h1>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Calendar Component */}
        <div className="lg:col-span-2">
          <Card>
            <CardHeader>
              <CardTitle>Task Calendar</CardTitle>
            </CardHeader>
            <CardContent>
              <Calendar
                mode="single"
                selected={selectedDate}
                onSelect={setSelectedDate}
                className="rounded-md border"
                modifiers={{
                  hasTask: (date) => getTasksForDate(date).length > 0,
                }}
                modifiersStyles={{
                  hasTask: {
                    backgroundColor: 'rgba(59, 130, 246, 0.1)',
                    borderRadius: '50%',
                  },
                }}
              />
            </CardContent>
          </Card>
        </div>

        {/* Task List for Selected Date */}
        <div>
          <Card>
            <CardHeader>
              <CardTitle>
                {selectedDate ? selectedDate.toLocaleDateString('en-US', {
                  weekday: 'long',
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric',
                }) : 'Select a date'}
              </CardTitle>
            </CardHeader>
            <CardContent>
              {selectedDateTasks.length > 0 ? (
                <div className="space-y-4">
                  {selectedDateTasks.map((task) => (
                    <div
                      key={task.id}
                      className="p-4 border rounded-lg hover:bg-gray-50 cursor-pointer"
                      onClick={() => router.push(`/designer/tasks/${task.id}`)}
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <h3 className="font-medium text-gray-900">{task.title}</h3>
                          {task.project_id && (
                            <p className="text-sm text-gray-500">
                              Project ID: {task.project_id}
                            </p>
                          )}
                        </div>
                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${getPriorityColor(task.priority)}`}>
                          {task.priority}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-gray-500 text-center py-4">
                  No tasks scheduled for this date
                </p>
              )}
            </CardContent>
          </Card>

          {/* Monthly Summary */}
          <Card className="mt-6">
            <CardHeader>
              <CardTitle>Monthly Summary</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <div className="flex justify-between">
                  <span className="text-gray-600">Total Tasks:</span>
                  <span className="font-medium">{monthTasks.length}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">High Priority:</span>
                  <span className="font-medium text-red-600">
                    {monthTasks.filter(t => t.priority === 'high').length}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Medium Priority:</span>
                  <span className="font-medium text-yellow-600">
                    {monthTasks.filter(t => t.priority === 'medium').length}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-600">Low Priority:</span>
                  <span className="font-medium text-green-600">
                    {monthTasks.filter(t => t.priority === 'low').length}
                  </span>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
