                <Select value={sortOrder} onValueChange={(value) => setSortOrder(value as 'asc' | 'desc')}>
                  <SelectTrigger><SelectValue placeholder="Order" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="desc">Descending</SelectItem>
                    <SelectItem value="asc">Ascending</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="mb-4 text-right">
                <Button variant="outline" onClick={() => setFileViewMode(fileViewMode === 'list' ? 'gallery' : 'list')}>
                  {fileViewMode === 'list' ? 'Switch to Gallery View' : 'Switch to List View'}
                </Button>
              </div>

              {/* File Display Area */}
              {filteredAndSortedFiles().length === 0 ? (
                <p>No files found for the current filter.</p>
              ) : fileViewMode === 'list' ? (
                <div className="space-y-2">
                  {filteredAndSortedFiles().map((file) => {
                    console.log(`[FilesTab] Rendering List Item: ${file.name}, Uploaded By: ${file.uploaded_by}`);
                    return (
                      <Card key={file.id || file.url} className="flex items-center p-3">
                        <div className="mr-3 shrink-0">{getFileIcon(file)}</div>
                        <div className="flex-grow">
                          <p className="font-medium truncate" title={file.name}>{file.name}</p>
                          <p className="text-xs text-gray-500">
                            {formatFileSize(file.size || 0)} - Uploaded: {formatDate(file.upload_date)}
                            {file.uploaded_by && ` by ${file.uploaded_by.charAt(0).toUpperCase() + file.uploaded_by.slice(1)}`}
                          </p>
                        </div>
                        <div className="ml-2 space-x-1 shrink-0">
                          <Button variant="outline" size="sm" onClick={() => handleFileDownload(file.url, file.name)} disabled={isSubmitting}>
                            <DownloadIcon className="h-4 w-4" />
                          </Button>
                          <Button variant="destructive" size="sm" onClick={() => handleFileDelete(file.url, file.name)} disabled={isSubmitting}>
                            Delete
                          </Button>
                        </div>
                      </Card>
                    );
                  })}
                </div>
              ) : ( // Gallery View
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                  {filteredAndSortedFiles().map((file) => {
                    console.log(`[FilesTab] Rendering Gallery Item: ${file.name}, Uploaded By: ${file.uploaded_by}`);
                    return (
                      <Card key={file.id || file.url} className="group relative aspect-square flex flex-col items-center justify-center overflow-hidden">
                        {isViewableImage(file) && file.url ? (
                          <img src={file.url} alt={file.name} className="h-full w-full object-cover" />
                        ) : (
                          <div className="p-2 text-center">
                            {getFileIcon(file)}
                            <p className="mt-1 text-xs truncate" title={file.name}>{file.name}</p>
                          </div>
                        )}
                        <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-50 transition-opacity flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 p-2">
                          <p className="text-white text-xs text-center truncate w-full mb-1" title={file.name}>{file.name}</p>
                          <div className="flex space-x-1">
                            <Button variant="outline" size="icon" className="bg-white/80 hover:bg-white" onClick={() => handleFileDownload(file.url, file.name)} disabled={isSubmitting}>
                              <DownloadIcon className="h-4 w-4 text-gray-700" />
                            </Button>
                            <Button variant="destructive" size="icon" className="bg-red-500/80 hover:bg-red-500" onClick={() => handleFileDelete(file.url, file.name)} disabled={isSubmitting}>
                              <span className="text-white">X</span>
                            </Button>
                          </div>
                        </div>
                      </Card>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="revisions">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>Project Revisions</CardTitle>
                <CardDescription>Track design iterations and feedback.</CardDescription>
              </div>
              <Button onClick={() => { setShowRevisionForm(!showRevisionForm); setIsEditingRevision(false); setCurrentRevisionId(null); setNewRevision({title: '', description: '', notes: '', selectedFiles: [], links: [{url:'', title:''}], status: 'pending'}); }}>
                {showRevisionForm && !isEditingRevision ? 'Cancel' : 'Add New Revision'}
              </Button>
            </CardHeader>
            <CardContent>
              {showRevisionForm && (
                <Card className="mb-6 p-4">
                  <h3 className="text-lg font-semibold mb-3">{isEditingRevision ? 'Edit Revision' : 'Create New Revision'}</h3>
                  <div className="space-y-3">
                    <input type="text" placeholder="Revision Title" value={newRevision.title} onChange={e => setNewRevision({...newRevision, title: e.target.value})} className="w-full p-2 border rounded" />
                    <Textarea placeholder="Description" value={newRevision.description} onChange={e => setNewRevision({...newRevision, description: e.target.value})} className="w-full p-2 border rounded" />
                    {/* We might add more fields here like file selection, links etc. later */}
                    <Select value={newRevision.status} onValueChange={status => setNewRevision({...newRevision, status: status as RevisionStatus})}>
                        <SelectTrigger><SelectValue placeholder="Set Status" /></SelectTrigger>
                        <SelectContent>
                            <SelectItem value="pending">Pending</SelectItem>
                            <SelectItem value="approved">Approved</SelectItem>
                            <SelectItem value="rejected">Rejected</SelectItem>
                            <SelectItem value="current">Current</SelectItem>
                        </SelectContent>
                    </Select>
                    <Button onClick={handleAddRevision} disabled={isSubmitting || !newRevision.title}>
                      {isSubmitting ? (isEditingRevision ? 'Updating...' : 'Saving...') : (isEditingRevision ? 'Update Revision' : 'Save Revision')}
                    </Button>
                  </div>
                </Card>
              )}

              <div className="space-y-4">
                {revisions.length === 0 && !showRevisionForm && <p>No revisions yet.</p>}
                {revisions.map(rev => (
                  <Card key={rev.id}>
                    <CardHeader>
                      <div className="flex justify-between items-center">
                        <CardTitle className="text-lg">{rev.title} (v{rev.version})</CardTitle>
                        <Badge className={cn(getRevisionStatusColor(rev.status))}>{formatRevisionStatus(rev.status)}</Badge>
                      </div>
                      <CardDescription>Created: {formatDate(rev.created_at)}</CardDescription>
                    </CardHeader>
                    <CardContent>
                      {rev.description && <p className="mb-2">{rev.description}</p>}
                      {/* Display associated files and links here if available */}
                      <div className="mt-2 space-x-2">
                        <Button variant="outline" size="sm" onClick={() => handleEditRevision(rev)} disabled={isSubmitting}>Edit</Button>
                        <Button variant="destructive" size="sm" onClick={() => handleDeleteRevision(rev.id)} disabled={isSubmitting}>Delete</Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {isWebDesign && (
          <TabsContent value="bir">
            <Card>
              <CardHeader>
                <CardTitle>Business Information Request</CardTitle>
                <CardDescription>
                  Review the information and files submitted by the client.
                </CardDescription>
              </CardHeader>
              <CardContent>
                {(() => {
                  console.log('[DesignerPage][BIR Tab] Attempting to render content. isLoadingBir:', isLoadingBir, 'birError:', birError);
                  if (isLoadingBir) {
                    return <p>Loading Business Information...</p>;
                  }
                  if (birError) {
                    return <p className="text-destructive">Error loading Business Information: {birError.message}</p>;
                  }
                  // Only render BusinessInfoGate if not loading and no error
                  return (
                    <BusinessInfoGate
                      projectId={id} 
                      projectType={type} 
                    />
                  );
                })()}
              </CardContent>
            </Card>
          </TabsContent>
        )}
      </Tabs>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ClockIcon, ArrowPathIcon, DocumentTextIcon } from '@heroicons/react/24/outline';
import { getUserProfile, getDesignerAssignedProjects } from '@/lib/api/client-api';
import Link from 'next/link';

export default function DesignerProjectsPage() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [projects, setProjects] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState('all');

  useEffect(() => {
    const loadProjects = async () => {
      try {
        setIsLoading(true);
        setError(null);

        // Get user profile
        const userProfile = await getUserProfile();

        // Check role
        if (userProfile?.role !== 'designer') {
          router.push('/dashboard');
          return;
        }

        // Fetch designer's assigned projects
        const assignedProjects = await getDesignerAssignedProjects();
        console.log('Fetched projects:', assignedProjects);

        // Ensure we have an array of projects
        if (Array.isArray(assignedProjects)) {
          setProjects(assignedProjects);
        } else {
          console.error('Expected array of projects but got:', typeof assignedProjects);
          setProjects([]);
        }
      } catch (err) {
        console.error('Error loading projects:', err);
        setError('Failed to load projects');
        // In development mode, add some mock data for testing
        if (process.env.NODE_ENV === 'development') {
          setProjects([
            {
              id: '1',
              title: 'Company Website Redesign',
              description: 'A complete overhaul of the corporate website with modern design principles and improved UX.',
              status: 'in_progress',
              type: 'web_design',
              deadline: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
              client_name: 'Acme Corporation'
            },
            {
              id: '2',
              title: 'Brand Identity Package',
              description: 'Creating a new logo, color palette, and brand guidelines for a tech startup.',
              status: 'pending',
              type: 'logo_design',
              deadline: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
              client_name: 'TechStart Inc.'
            },
            {
              id: '3',
              title: 'Social Media Campaign',
              description: 'A series of graphics for Instagram, Facebook, and Twitter to promote summer sale.',
              status: 'completed',
              type: 'social_graphics',
              deadline: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString(),
              client_name: 'Fashion Boutique'
            }
          ]);
        }
      } finally {
        setIsLoading(false);
      }
    };

    loadProjects();
  }, [router]);

  // Filter projects based on the selected tab
  const filteredProjects = projects.filter(project => {
    if (activeTab === 'all') return true;
    if (activeTab === 'active') return project.status !== 'completed' && project.status !== 'cancelled';
    if (activeTab === 'completed') return project.status === 'completed';
    if (activeTab === 'upcoming') {
      if (!project.deadline) return false;
      const deadline = new Date(project.deadline);
      const now = new Date();
      const diffDays = Math.ceil((deadline.getTime() - now.getTime()) / (1000 * 3600 * 24));
      return diffDays <= 7 && diffDays >= 0 && project.status !== 'completed' && project.status !== 'cancelled';
    }
    return true;
  });

  // Get status badge color
  const getStatusColor = (status: string) => {
    switch(status?.toLowerCase()) {
      case 'completed': return 'bg-green-500 text-white';
      case 'in_progress': return 'bg-blue-500 text-white';
      case 'pending': return 'bg-yellow-500 text-white';
      case 'todo': return 'bg-gray-500 text-white';
      default: return 'bg-gray-500 text-white';
    }
  };

  // Get type badge color
  const getTypeColor = (type: string) => {
    switch(type?.toLowerCase()) {
      case 'web_design': return 'bg-purple-100 text-purple-800 border-purple-300';
      case 'logo_design': return 'bg-indigo-100 text-indigo-800 border-indigo-300';
      case 'social_graphics': return 'bg-pink-100 text-pink-800 border-pink-300';
      default: return 'bg-gray-100 text-gray-800 border-gray-300';
    }
  };

  // Format date helper
  const formatDate = (dateString: string | null) => {
    if (!dateString) return 'Not set';
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    });
  };

  const formatProjectType = (type: string) => {
    if (!type) return 'Project';
    return type.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <ArrowPathIcon className="h-8 w-8 text-red-500 animate-spin" />
      </div>
    );
  }

  if (error && projects.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-red-50 p-4 rounded-md">
          <p className="text-red-700">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">My Projects</h1>
      </div>

      <Tabs defaultValue="all" value={activeTab} onValueChange={setActiveTab} className="mb-8">
        <TabsList className="bg-slate-200 dark:bg-slate-800 p-1 rounded-lg">
          <TabsTrigger 
            value="all" 
            className="px-3 py-1.5 text-sm font-medium rounded-md text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-slate-100 data-[state=active]:bg-primary-600 data-[state=active]:text-white dark:data-[state=active]:bg-primary-500 dark:data-[state=active]:text-white"
          >
            All Projects
          </TabsTrigger>
          <TabsTrigger 
            value="active" 
            className="px-3 py-1.5 text-sm font-medium rounded-md text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-slate-100 data-[state=active]:bg-primary-600 data-[state=active]:text-white dark:data-[state=active]:bg-primary-500 dark:data-[state=active]:text-white"
          >
            Active
          </TabsTrigger>
          <TabsTrigger 
            value="upcoming" 
            className="px-3 py-1.5 text-sm font-medium rounded-md text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-slate-100 data-[state=active]:bg-primary-600 data-[state=active]:text-white dark:data-[state=active]:bg-primary-500 dark:data-[state=active]:text-white"
          >
            Upcoming Deadlines
          </TabsTrigger>
          <TabsTrigger 
            value="completed" 
            className="px-3 py-1.5 text-sm font-medium rounded-md text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-slate-100 data-[state=active]:bg-primary-600 data-[state=active]:text-white dark:data-[state=active]:bg-primary-500 dark:data-[state=active]:text-white"
          >
            Completed
          </TabsTrigger>
        </TabsList>

        <TabsContent value="all" className="mt-6">
          <h2 className="text-lg font-medium text-gray-900 dark:text-gray-200 mb-4">All Projects ({projects.length})</h2>
          <div className="grid grid-cols-1 gap-6">
            {renderProjects(filteredProjects)}
          </div>
        </TabsContent>

        <TabsContent value="active" className="mt-6">
          <h2 className="text-lg font-medium text-gray-900 dark:text-gray-200 mb-4">Active Projects ({
            projects.filter(p => p.status !== 'completed' && p.status !== 'cancelled').length
          })</h2>
          <div className="grid grid-cols-1 gap-6">
            {renderProjects(filteredProjects)}
          </div>
        </TabsContent>

        <TabsContent value="upcoming" className="mt-6">
          <h2 className="text-lg font-medium text-gray-900 dark:text-gray-200 mb-4">Upcoming Deadlines</h2>
          <div className="grid grid-cols-1 gap-6">
            {renderProjects(filteredProjects)}
          </div>
        </TabsContent>

        <TabsContent value="completed" className="mt-6">
          <h2 className="text-lg font-medium text-gray-900 dark:text-gray-200 mb-4">Completed Projects ({
            projects.filter(p => p.status === 'completed').length
          })</h2>
          <div className="grid grid-cols-1 gap-6">
            {renderProjects(filteredProjects)}
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );

  // Helper function to render project cards
  function renderProjects(projectsList: any[]) {
    if (projectsList.length === 0) {
      return (
        <Card className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700">
          <CardContent className="p-6">
            <p className="text-center text-gray-600 dark:text-gray-400">No projects found</p>
          </CardContent>
        </Card>
      );
    }

    return projectsList.map((project) => (
      <Card key={project.id} className="overflow-hidden hover:shadow-xl transition-shadow duration-200 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700">
        <CardContent className="p-6">
          <div className="flex justify-between items-start">
            <div className="flex-1">
              <h3 className="text-lg font-medium text-gray-900 dark:text-white">
                <Link href={`/designer/projects/${project.type || 'web_design'}/${project.id}`} className="hover:underline text-primary-600 dark:text-primary-400">
                  {project.name || project.title}
                </Link>
              </h3>

              <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
                {project.description?.substring(0, 150)}
                {project.description?.length > 150 ? '...' : ''}
              </p>

              <div className="mt-3 flex flex-wrap items-center gap-2">
                <Badge className={getStatusColor(project.status)}>
                  {project.status?.replace('_', ' ')}
                </Badge>

                {project.deadline && (
                  <span className="text-xs text-gray-500 dark:text-gray-400 flex items-center">
                    <ClockIcon className="h-3 w-3 mr-1" />
                    Due {formatDate(project.deadline)}
                  </span>
                )}

                <Badge variant="outline" className={getTypeColor(project.type)}>
                  {formatProjectType(project.type) || 'Web Design'}
                </Badge>

                {project.client_name && (
                  <span className="text-xs text-gray-500 dark:text-gray-400">
                    Client: {project.client_name}
                  </span>
                )}
              </div>
            </div>

            <div className="ml-4">
              <Button 
                className="bg-primary-600 hover:bg-primary-700 text-white"
                size="sm" 
                onClick={() => router.push(`/designer/projects/${project.type || 'web_design'}/${project.id}`)}
              >
                <DocumentTextIcon className="h-4 w-4 mr-2" />
                View Details
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    ));
  }
}

