}

/**
 * NOTE: This page currently uses placeholder data. Actual data fetching
 * needs to be implemented, including the getProjectForDesigner function.
 *
 * Designer view for a specific project's details.
 */
export default function DesignerProjectDetailsPage() {
    const { projectType, id } = useParams(); // Get params from URL
    const router = useRouter(); // Initialize useRouter
    const { user, isLoading: authLoading } = useAuth();
    const [project, setProject] = useState<ProjectDetails | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const { toast } = useToast(); // Get toast function from the hook

    useEffect(() => {
        const loadProject = async () => {
            const projectId = Array.isArray(id) ? id[0] : id;
            // projectType from URL params can be used for validation if needed, but API path is specific
            const currentProjectType = 'web_design'; // Hardcoded as this page is for web_design

            if (!projectId || !user) { // User must be loaded to ensure auth checks on API pass
                setIsLoading(false); // Stop loading if no projectId or user
                return;
            }

            setIsLoading(true);
            setError(null);
            try {
                const response = await fetch(`/api/projects/web_design/${projectId}`);
                if (!response.ok) {
                    const errorData = await response.json().catch(() => ({ error: `HTTP error! status: ${response.status}` }));
                    // Check for 403/404 for redirect
                    if (response.status === 403 || response.status === 404) {
                        toast({
                            title: response.status === 403 ? 'Access Denied' : 'Project Not Found',
                            description: errorData.error || (response.status === 403 ? "You don't have permission to view this project." : "The requested project does not exist."),
                            variant: 'destructive',
                        });
                        router.push('/designer/projects'); // Redirect to projects list
                        return; // Stop further processing
                    }
                    throw new Error(errorData.error || `Failed to fetch project details. Status: ${response.status}`);
                }
                const fetchedProject = await response.json();
                setProject(fetchedProject as ProjectDetails);
            } catch (err: any) {
                console.error("Error loading project for designer:", err);
                setError(err.message || 'Failed to load project details.');
                toast({
                    title: 'Error Loading Project',
                    description: err.message || 'An unexpected error occurred.',
                    variant: 'destructive',
                });
                setProject(null);
            } finally {
                setIsLoading(false);
            }
        };

        if (!authLoading) { // Only run if auth state is resolved
            loadProject();
        }
    }, [id, user, authLoading]); // projectType from URL can be added if used in fetch path or logic

    if (isLoading || authLoading) {
        // Basic loading state
        return (
            <div className="container mx-auto p-4 space-y-6">
                <Skeleton className="h-8 w-3/4 mb-4" />
                <Skeleton className="h-40 rounded-lg" />
                 <Skeleton className="h-60 rounded-lg" />
            </div>
        );
    }

    if (error && !project) { // Show error only if no placeholder is set
        return <p className="text-destructive text-center p-4">Error: {error}</p>;
    }

    if (!project) {
        // This might briefly show if loading or if project is null after an error without explicit error message shown
        return <p className="text-center p-4">Loading project data or project not found...</p>;
    }

    return (
        <div className="container mx-auto p-4 space-y-8">
            <h1 className="text-3xl font-bold text-gray-800">{project.title} (Designer View)</h1>

            {/* Placeholder for other project details */}
            <Card>
                 <CardHeader><CardTitle>Project Summary</CardTitle></CardHeader>
                 <CardContent>
                    <p>Project ID: {project.id}</p>
                    <p>Type: {project.project_type}</p>
                    {project.description && <p>Description: {project.description}</p>}
                    {project.client && <p>Client: {project.client.full_name || project.client.email}</p>}
                 </CardContent>
            </Card>

            {/* Integrate Business Info Gate - Only show if web design */}
            {(() => {
                console.log('[DesignerPage] Attempting to render BusinessInfoGate. Project Data:', project);
                if (project && project.id && project.project_type === 'web_design') {
                    return (
                         <Card>
                            {/* <CardHeader>
                                <CardTitle>Business Information & Client Files</CardTitle>
                            </CardHeader> */}
                            <CardContent>
                                <BusinessInfoGate 
                                    projectId={project.id}
                                    projectType={project.project_type} // This will be 'web_design'
                                />
                            </CardContent>
                        </Card>
                    );
                }
                return null;
            })()}

             {/* Placeholder for tasks, files etc. */}
              <Card>
                 <CardHeader><CardTitle>Tasks</CardTitle></CardHeader>
                 <CardContent><p>Tasks assigned for this project...</p></CardContent>
            </Card>

        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ArrowPathIcon } from '@heroicons/react/24/outline';
import { getUserProfile, getDesignerTasks, updateTaskStatus } from '@/lib/api/client-api';
import { DesignerTask } from '@/lib/types/task';

export default function DesignerTasksPage() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [tasks, setTasks] = useState<DesignerTask[]>([]);
  const [filter, setFilter] = useState<'all' | 'todo' | 'in_progress' | 'completed'>('all');

  useEffect(() => {
    const loadTasks = async () => {
      try {
        setIsLoading(true);
        setError(null);

        // Get user profile
        const userProfile = await getUserProfile();

        // Check role
        if (userProfile?.role !== 'designer') {
          router.push('/dashboard');
          return;
        }

        // Fetch designer's tasks
        const designerTasks = await getDesignerTasks(userProfile.id);
        setTasks(designerTasks);
      } catch (err) {
        console.error('Error loading tasks:', err);
        setError('Failed to load tasks');
      } finally {
        setIsLoading(false);
      }
    };

    loadTasks();
  }, [router]);

  const handleStatusUpdate = async (taskId: string, newStatus: string) => {
    try {
      await updateTaskStatus(taskId, newStatus);
      // Refresh tasks after update
      const userProfile = await getUserProfile();
      if (userProfile?.id) {
        const updatedTasks = await getDesignerTasks(userProfile.id);
        setTasks(updatedTasks);
      }
    } catch (err) {
      console.error('Error updating task status:', err);
      setError('Failed to update task status');
    }
  };

  // Filter tasks based on status
  const filteredTasks = tasks.filter(task => {
    if (filter === 'all') return true;
    return task.status === filter;
  });

  // Get badge color based on priority
  const getPriorityColor = (priority: string) => {
    switch(priority) {
      case 'high': return 'bg-red-100 text-red-800';
      case 'medium': return 'bg-yellow-100 text-yellow-800';
      case 'low': return 'bg-green-100 text-green-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  // Get badge color based on status
  const getStatusColor = (status: string) => {
    switch(status) {
      case 'todo': return 'bg-blue-100 text-blue-800';
      case 'in_progress': return 'bg-yellow-100 text-yellow-800';
      case 'completed': return 'bg-green-100 text-green-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  // Format date helper
  const formatDate = (dateString: string | null) => {
    if (!dateString) return 'Not set';
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <ArrowPathIcon className="h-8 w-8 text-gray-500 animate-spin" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-red-50 p-4 rounded-md">
          <p className="text-red-700">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-2xl font-bold text-gray-900">My Tasks</h1>
        <div className="flex space-x-2">
          <Button
            variant={filter === 'all' ? 'default' : 'outline'}
            onClick={() => setFilter('all')}
          >
            All
          </Button>
          <Button
            variant={filter === 'todo' ? 'default' : 'outline'}
            onClick={() => setFilter('todo')}
          >
            Todo
          </Button>
          <Button
            variant={filter === 'in_progress' ? 'default' : 'outline'}
            onClick={() => setFilter('in_progress')}
          >
            In Progress
          </Button>
          <Button
            variant={filter === 'completed' ? 'default' : 'outline'}
            onClick={() => setFilter('completed')}
          >
            Completed
          </Button>
        </div>
      </div>

      <div className="grid gap-6">
        {filteredTasks.map((task) => (
          <Card key={task.id}>
            <CardContent className="p-6">
              <div className="flex justify-between items-start">
                <div className="space-y-1">
                  <h3 className="text-lg font-medium text-gray-900">{task.title}</h3>
                  {task.description && (
                    <p className="text-sm text-gray-500">{task.description}</p>
                  )}
                  {task.project_id && (
                    <p className="text-sm text-gray-500">
                      Project ID: {task.project_id}
                    </p>
                  )}
                  <div className="flex items-center space-x-2">
                    <Badge className={getPriorityColor(task.priority)}>
                      {task.priority}
                    </Badge>
                    <Badge className={getStatusColor(task.status)}>
                      {task.status.replace('_', ' ')}
                    </Badge>
                  </div>
                  {task.due_date && (
                    <p className="text-sm text-gray-500">
                      Due: {formatDate(task.due_date)}
                    </p>
                  )}
                </div>
                <div className="flex space-x-2">
                  {task.status !== 'completed' && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleStatusUpdate(task.id, 'completed')}
                    >
                      Mark Complete
                    </Button>
                  )}
                  {task.status === 'todo' && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleStatusUpdate(task.id, 'in_progress')}
                    >
                      Start Task
                    </Button>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
        {filteredTasks.length === 0 && (
          <Card>
            <CardContent className="p-6 text-center text-gray-500">
              No tasks found for the selected filter
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { createApiClient } from '@/lib/api/server-utils';
import { createAdminClient } from '@/lib/api/server';

export const dynamic = 'force-dynamic';

type RoleFormat = 'both' | 'metadata' | 'profile' | 'string';

// Helper to verify admin access
async function verifyAdminAccess() {
  try {
    // Create API client for authentication
    const supabase = createApiClient();

    // Get current user
    const { data: { user }, error: userError } = await supabase.auth.getUser();

    if (userError || !user) {
      return { authorized: false, error: 'Authentication required' };
    }

    // Check if user has admin role
    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('role')
      .eq('id', user.id)
      .single();

    if (profileError || !profile) {
      return { authorized: false, error: 'Could not verify user role' };
    }

    if (profile.role !== 'admin') {
      return { authorized: false, error: 'Admin access required' };
    }

    return { authorized: true, user };
  } catch (error) {
    console.error('Error verifying admin access:', error);
    return { authorized: false, error: 'Error verifying admin access' };
  }
}

export async function POST(request: NextRequest) {
  try {
    // Verify admin access
    const { authorized, error } = await verifyAdminAccess();

    if (!authorized) {
      return NextResponse.json(
        { error: error || 'Unauthorized' },
        { status: 403 }
      );
    }

    const data = await request.json();
    const { email, password, fullName, roleFormat = 'both' } = data;

    if (!email || !password || !fullName) {
      return NextResponse.json(
        { error: 'Missing required fields' },
        { status: 400 }
      );
    }

    // Create admin client
    const adminClient = createAdminClient();

    console.log(`Creating designer with role format: ${roleFormat}`);

    // Step 1: Create user based on the role format
    let userData;
    let userError;

    // Store role based on specified format
    if (roleFormat === 'metadata' || roleFormat === 'both' || roleFormat === 'string') {
      // Create user with role in app_metadata
      const appMetadata = roleFormat === 'string' 
        ? { role: JSON.stringify('designer') }  // Store as properly typed object
        : { role: 'designer' };                 // Store as object (normal)

      const { data, error } = await adminClient.auth.admin.createUser({
        email,
        password,
        email_confirm: true,
        user_metadata: {
          full_name: fullName,
        },
        app_metadata: appMetadata,
      });

      userData = data;
      userError = error;
    } else {
      // Create user without role in metadata
      const { data, error } = await adminClient.auth.admin.createUser({
        email,
        password,
        email_confirm: true,
        user_metadata: {
          full_name: fullName,
        },
      });

      userData = data;
      userError = error;
    }

    if (userError) {
      console.error('Error creating user:', userError);
      return NextResponse.json(
        { error: userError.message },
        { status: 500 }
      );
    }

    if (!userData?.user) {
      return NextResponse.json(
        { error: 'Failed to create user' },
        { status: 500 }
      );
    }

    // Step 2: If using profile table or both, add to profiles table
    let profileData = null;
    let profileError = null;

    if (roleFormat === 'profile' || roleFormat === 'both') {
      const { data, error } = await adminClient
        .from('profiles')
        .upsert({
          id: userData.user.id,
          email: email,
          full_name: fullName,
          role: 'designer',
          updated_at: new Date().toISOString(),
        })
        .select();

      profileData = data;
      profileError = error;

      if (profileError) {
        console.error('Error creating profile:', profileError);
        // Continue anyway since we created the user
      }
    }

    // Step 3: Verify the user was created
    const { data: verifiedUser, error: verifyError } = await adminClient.auth.admin.getUserById(
      userData.user.id
    );

    if (verifyError) {
      console.error('Error verifying user:', verifyError);
    }

    return NextResponse.json({
      success: true,
      user: userData.user,
      profile: profileData?.[0] || null,
      verifiedUser: verifiedUser?.user || null,
      roleFormat,
    });
  } catch (error) {
    console.error('Error in debug create-designer:', error);
    return NextResponse.json(
      { 
        error: error instanceof Error ? error.message : 'An unknown error occurred',
        success: false 
      },
      { status: 500 }
    );
  }
}

