// PUT handler to update a user
export async function PUT(request: NextRequest, { params }: { params: { id: string } }) {
  try {
    // Verify admin access
    const { authorized, error } = await verifyAdminAccess();

    if (!authorized) {
      return NextResponse.json(
        { error: error || 'Unauthorized' },
        { status: 403 }
      );
    }

    const userId = params.id;

    if (!userId) {
      return NextResponse.json(
        { error: 'User ID is required' },
        { status: 400 }
      );
    }

    // Get update data
    const updates = await request.json();

    // Create admin client
    const adminClient = createAdminClient();

    // Update user metadata if provided
    if (updates.email || updates.full_name) {
      const { error: authError } = await adminClient.auth.admin.updateUserById(userId, {
        email: updates.email,
        user_metadata: {
          full_name: updates.full_name
        }
      });

      if (authError) {
        console.error('Error updating auth user:', authError);
        return NextResponse.json(
          { error: 'Failed to update user auth data' },
          { status: 500 }
        );
      }
    }

    // Update profile if provided
    if (Object.keys(updates).length > 0) {
      // Remove auth-only fields
      const { email: _email, password: _password, ...profileUpdates } = updates;

      // Add updated timestamp
      profileUpdates.updated_at = new Date().toISOString();

      const { data: profile, error: profileError } = await adminClient
        .from('profiles')
        .upsert({
          id: userId,
          ...profileUpdates
        })
        .select()
        .single();

      if (profileError) {
        console.error('Error updating profile:', profileError);
        return NextResponse.json(
          { error: 'Failed to update user profile' },
          { status: 500 }
        );
      }

      return NextResponse.json(profile);
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('Error in update user API:', error);
    return NextResponse.json(
      { error: 'Server error processing request' },
      { status: 500 }
    );
  }
}

