// POST handler to create a new user or update an existing one
export async function POST(request: NextRequest) {
  try {
    // Verify admin access
    const { authorized, error } = await verifyAdminAccess();

    if (!authorized) {
      return NextResponse.json(
        { error: error || 'Unauthorized' },
        { status: 403 }
      );
    }

    // Get request data
    const userData = await request.json();

    // Validate required fields
    if (!userData.email) {
      return NextResponse.json(
        { error: 'Email is required' },
        { status: 400 }
      );
    }

    // Create admin client
    const adminClient = createAdminClient();

    // Check if user already exists by email
    const { data, error: _searchError } = await adminClient.auth.admin.listUsers({
      perPage: 1
    });

    // Manually filter the users by email as the filters parameter isn't supported in the type
    const existingUser = data?.users.find(user => user.email === userData.email);

    let userId;

    // If user doesn't exist, create them
    if (!existingUser) {
      // Create new user in Auth
      const { data: newUser, error: createError } = await adminClient.auth.admin.createUser({
        email: userData.email,
        password: userData.password || null,
        email_confirm: true,
        user_metadata: {
          full_name: userData.full_name || '',
          company: userData.company || ''
        }
      });

      if (createError) {
        console.error('Error creating user:', createError);
        return NextResponse.json(
          { error: 'Failed to create user' },
          { status: 500 }
        );
      }

      userId = newUser.user.id;
    } else {
      userId = existingUser.id;
    }

    // Update or create profile
    const { data: profile, error: profileError } = await adminClient
      .from('profiles')
      .upsert({
        id: userId,
        full_name: userData.full_name,
        email: userData.email,
        role: userData.role || 'client',
        company: userData.company,
        updated_at: new Date().toISOString()
      })
      .select()
      .single();

    if (profileError) {
      console.error('Error updating profile:', profileError);
      return NextResponse.json(
        { error: 'Failed to update user profile' },
        { status: 500 }
      );
    }

    return NextResponse.json(profile);
  } catch (error) {
    console.error('Error in create/update user API:', error);
    return NextResponse.json(
      { error: 'Server error processing request' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createServerClient, type CookieOptions } from '@supabase/ssr';
import { cookies } from 'next/headers';

/**
 * POST handler for server-side logout
 * This ensures cookies are properly cleared
 */
export async function POST(_request: NextRequest) {
  // Create a Supabase client
  const cookieStore = cookies();

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        get(name: string) {
          return cookieStore.get(name)?.value;
        },
        set(name: string, value: string, options: CookieOptions) {
          cookieStore.set({ name, value, ...options });
        },
        remove(name: string, options: CookieOptions) {
          cookieStore.set({ name, value: '', ...options });
        },
      },
    }
  );

  // Call sign out on the server to clear the session cookie
  await supabase.auth.signOut();

  // Set up response
  const response = NextResponse.json({ success: true });

  // Get all cookies
  const allCookies = cookieStore.getAll();

  // Explicitly expire all auth-related cookies
  allCookies.forEach(cookie => {
    if (cookie.name.includes('supabase') || cookie.name.includes('sb-')) {
      response.cookies.set({
        name: cookie.name,
        value: '',
        expires: new Date(0), // Expire immediately
        path: '/',
      });
    }
  });

  return response;
}

