export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const router = useRouter();
  const { user, isLoading: authIsLoading, error: authContextError } = useAuthContext();

  // On component mount OR when auth state changes, check if already logged in
  useEffect(() => {
    // Wait for AuthContext to finish loading
    if (authIsLoading) {
      return; 
    }

    // Check for errors from AuthContext initialization
    if (authContextError) {
      console.error("AuthContext Error:", authContextError);
      return;
    }

    // If loading is finished and user exists, fetch profile and redirect
    if (user) {
      const handleRedirect = async () => {
        try {
          console.log('User authenticated, fetching profile for redirect...');
          const profile = await getUserProfile();
          const role = profile?.role as UserRole; // Assuming role is directly on profile
          console.log('User role determined as:', role);

          let targetPath = '/'; // Default path
          switch (role) {
            case 'admin':
              targetPath = '/admin'; // Or specific admin dashboard like /admin/dashboard
              break;
            case 'designer':
              targetPath = '/designer'; // Or specific designer dashboard
              break;
            case 'client':
              targetPath = '/client'; // Or specific client dashboard
              break;
            // Add other roles like 'partner' if necessary
            default:
              console.warn(`Unknown or missing role: ${role}, redirecting to default.`);
              // Decide on a sensible default, maybe client dashboard or root
              targetPath = '/client'; // Example: Default to client dashboard
          }

          // Check for redirectedFrom query parameter (optional, might override role-based redirect)
          const redirectedFrom = new URLSearchParams(window.location.search).get('redirectedFrom');
          if (redirectedFrom) {
              console.log(`Redirecting to query parameter: ${redirectedFrom}`);
              router.push(redirectedFrom);
          } else {
              console.log(`Redirecting based on role to: ${targetPath}`);
              router.push(targetPath); 
          }

        } catch (error) {
          console.error('Failed to fetch user profile for redirect:', error);
          // Handle error - maybe redirect to a generic dashboard or show an error
          setLoginError('Could not determine user role. Redirecting to default page.');
          router.push('/'); // Fallback redirect
        }
      };

      handleRedirect();

    } 

  }, [user, authIsLoading, authContextError, router]); // Depend on context state and router

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true); 
    setLoginError(null);

    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) {
        setLoginError('Invalid email or password. Please try again.'); 
        console.error('Supabase Auth Error:', error.message);
        setIsSubmitting(false); 
        return;
      }

    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      setLoginError('An unexpected error occurred. Please try again later.');
      console.error('Login Submit Error:', errorMessage, error);
      setIsSubmitting(false); // Ensure loading stops on unexpected error
    } 
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-gray-50 dark:bg-gray-900">
      <div className="w-full max-w-md">
        <Card className="p-6">
          <h1 className="text-2xl font-bold mb-6 text-center">Sign in to your account</h1>

          <form onSubmit={handleSubmit}>
            <div className="mb-4">
              <label htmlFor="email" className="block text-sm font-medium mb-1">
                Email
              </label>
              <input
                id="email"
                name="email"
                type="email"
                autoComplete="email"
                required
                className="w-full p-2 border rounded dark:bg-gray-800 dark:border-gray-700 dark:text-white disabled:opacity-75"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                disabled={isSubmitting}
              />
            </div>

            <div className="mb-6">
              <label htmlFor="password" className="block text-sm font-medium mb-1">
                Password
              </label>
              <input
                id="password"
                name="password"
                type="password"
                autoComplete="current-password"
                required
                className="w-full p-2 border rounded dark:bg-gray-800 dark:border-gray-700 dark:text-white disabled:opacity-75"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                disabled={isSubmitting}
              />
            </div>

            {loginError && (
              <div className="mb-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded">
                {loginError}
              </div>
            )}

            <div className="mb-4 text-right">
              <a
                href="/reset-password"
                className="text-sm text-blue-600 hover:underline"
              >
                Forgot your password?
              </a>
            </div>

            <div className="flex flex-col gap-2 mt-6">
              <Button
                type="submit"
                variant="primary"
                disabled={isSubmitting}
                isLoading={isSubmitting}
                className="w-full"
              >
                {isSubmitting ? 'Signing in...' : 'Sign in'}
              </Button>
            </div>
          </form>

          <div className="mt-6 text-center">
            <p className="text-sm text-gray-600">
              Don&apos;t have an account?{' '}
              <a href="/register" className="text-blue-600 hover:underline">
                Register here
              </a>
            </p>
          </div>
        </Card>
      </div>
    </div>
  );
}

'use client';

import { ChangeEvent, useState, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input'; // Use Shadcn Input for consistency
import { useToast } from '@/components/ui/use-toast';
import { cn } from '@/lib/utils'; // Assuming you have cn utility
import { BirFileType, BirFileRow } from '@/lib/types/bir'; // Import from the new shared location

interface Props {
  birId: string;
  fileType: BirFileType; // This might be used to categorize on client or passed to record-file if needed
  onUploadSuccess?: (uploadedFile: BirFileRow) => void;
  className?: string;
  accept?: string;
  disabled?: boolean;
}

export default function BirFileUploader({
  birId,
  fileType, // Keep fileType prop for potential future use or if needed by record-file
  onUploadSuccess,
  className,
  accept = 'image/*,application/pdf,.zip,.txt', // Added .txt to default accepted types
  disabled = false,
}: Props) {
  const { toast } = useToast();
  const [uploading, setUploading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploading(true);
    let allUploadsSuccessful = true;

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      try {
        // Step 1: Get the signed URL from our backend
        const createUrlResponse = await fetch('/api/bir/create-upload-url', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            birId: birId,
            filename: file.name,
            mime: file.type || 'application/octet-stream'
          }),
        });

        if (!createUrlResponse.ok) {
          const errorResult = await createUrlResponse.json().catch(() => ({ error: "Failed to get signed URL", details: createUrlResponse.statusText }));
          throw new Error(errorResult.error || `Failed to get signed URL for ${file.name}: ${errorResult.details}`);
        }

        const { uploadUrl, objectKey } = await createUrlResponse.json();

        // Step 2: Upload the file directly to Supabase Storage
        const uploadToStorageResponse = await fetch(uploadUrl, {
          method: 'PUT',
          headers: { 'Content-Type': file.type || 'application/octet-stream' },
          body: file,
        });

        // ADD DETAILED LOGGING FOR STEP 2 RESPONSE
        console.log(`[BirFileUploader] Storage upload attempt for ${file.name}:`, {
          url: uploadUrl,
          status: uploadToStorageResponse.status,
          statusText: uploadToStorageResponse.statusText,
          ok: uploadToStorageResponse.ok,
          // Attempt to get response body if not ok, for more details
          bodyAttempt: !uploadToStorageResponse.ok ? await uploadToStorageResponse.text().catch(() => 'Could not read error body') : 'N/A'
        });

        if (!uploadToStorageResponse.ok) {
          throw new Error(`Storage upload failed for ${file.name}: ${uploadToStorageResponse.statusText} (status: ${uploadToStorageResponse.status})`);
        }

        // Step 3: Record the file metadata in our database
        const recordFileResponse = await fetch('/api/bir/record-file', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            birId: birId,
            objectKey: objectKey,
            size: file.size,
            mime: file.type || 'application/octet-stream',
            originalName: file.name,
            fileType: fileType,
          }),
        });

        if (!recordFileResponse.ok) {
          const errorResult = await recordFileResponse.json().catch(() => ({ error: "Failed to record file metadata", details: recordFileResponse.statusText }));
          throw new Error(errorResult.error || `Failed to record file metadata for ${file.name}: ${errorResult.details}`);
        }

        const recordedFileResult = await recordFileResponse.json();

        toast({
          title: 'File Uploaded Successfully',
          description: `${file.name}`,
        });

        if (recordedFileResult.file) {
          onUploadSuccess?.(recordedFileResult.file as BirFileRow);
        } else {
          console.warn(`record-file API did not return the file object for ${file.name}. onUploadSuccess might not have detailed data.`);
        }

      } catch (error: any) {
        allUploadsSuccessful = false;
        console.error(`Upload process error for ${file.name}:`, error);
        toast({
          title: `Upload Failed for ${file.name}`,
          description: error.message || 'An unknown error occurred during upload.',
          variant: 'destructive',
        });
        // Optionally, break the loop if one file fails, or continue trying others
        // For now, it continues.
      }
    }

    if (inputRef.current) {
      inputRef.current.value = ''; // Reset input after all files are processed
    }
    setUploading(false);

    if (allUploadsSuccessful && files.length > 0) {
      // This callback might need adjustment if it's intended for overall success.
      // For now, onUploadSuccess is called for each successful file.
      // If a general "all done" notification is needed, that's a separate consideration.
    }
  };

  // Map file type enum to human-readable label
  const getButtonLabel = (type: BirFileType) => {
    switch (type) {
      case BirFileType.Logo: return 'Logo';
      case BirFileType.StyleGuide: return 'Style Guide';
      case BirFileType.Photo: return 'Photo/Asset';
      case BirFileType.Certificate: return 'Certificate/License';
      case BirFileType.Misc: return 'Miscellaneous';
      default: return 'File';
    }
  };

  const buttonLabel = getButtonLabel(fileType);
  const inputId = `${fileType}-upload-${birId}`;

  return (
    <div className={cn('flex flex-col items-start', className)}>
      <Input
        id={inputId}
        type="file"
        className="hidden"
        onChange={handleFileChange}
        ref={inputRef}
        accept={accept} // Use the accept prop
        disabled={uploading || disabled}
        multiple // Allow multiple file selection
      />
      <Button
        type="button"
        variant="outline"
        onClick={() => inputRef.current?.click()}
        disabled={uploading || disabled}
        aria-label={`Upload ${buttonLabel}`}
      >
        {uploading ? 'Uploading...' : `Upload ${buttonLabel}`}
      </Button>
    </div>
  );
}

