'use client';

import React from "react";
import { LucideIcon } from "lucide-react";
import clsx from "clsx";
import { format, parseISO } from "date-fns";
import { ProjectStage } from "@/lib/types/project";

/**
 * Configuration object describing a single stage in the timeline.
 */
export interface StageConfig {
  /** Matching enum key in `ProjectStage` */
  key: ProjectStage;
  /** Human-readable label displayed under the dot */
  label: string;
  /** Lucide icon shown inside the dot */
  icon: LucideIcon;
}

export interface ProjectTimelineProps {
  /** Ordered list of stages for this project type */
  stages: StageConfig[];
  /** The stage currently in progress */
  currentStage: ProjectStage | null;
  /** Map of stage → ISO date string when that stage was completed */
  stageDates: Record<ProjectStage, string | null>;
}

// Type for the visual properties derived from a stage's status
interface StageVisualProperties {
  dotBg: string;
  dotBr: string;
  icon: string;
  label: string;
  bar: string;
}

/**
 * Renders a visual timeline for a project, indicating current, completed,
 * and pending stages with distinct colors and icons, based on a precise specification.
 *
 * Visual Rules:
 * - Each dot (stage) has one of three statuses: completed (GREEN), current/active (BLUE), or pending (GRAY).
 * - Each connecting bar segment belongs to the dot at its left/upper end and inherits that dot's color for its full length.
 * - Example Flow: [completed-dot]─green─[completed]─green─…─[active]─blue─[pending]─gray─[pending]─gray
 *
 * Status Algorithm:
 * - A stage is 'completed' if its index is before the current stage's index.
 * - A stage is 'active' if its index matches the current stage's index.
 * - A stage is 'pending' if its index is after the current stage's index.
 * - Special Case: If the *last* stage is 'active' AND has a completion date, it's treated as 'completed' (all-green timeline).
 * - If `currentStageKey` is not found, all stages default to 'pending'.
 *
 * Color Palette (example, see `getVisualProperties` for exact Tailwind classes):
 * - Completed: green-600 / dark:green-500 (dot, label, bar); text-white (icon).
 * - Active: blue-600 / dark:blue-500 (dot border, icon, label, bar); bg-blue-50 (dot bg).
 * - Pending: gray-400 / dark:gray-600 (dot border, bar with opacity); bg-gray-200 (dot bg); text-gray-500 (icon, label).
 *
 * Layout:
 * - Desktop (>=md): Interleaved [DOT_GROUP] ---bar--- [DOT_GROUP] layout, dots vertically centered with bars.
 * - Mobile (<md): Stacked dot groups with vertical connectors.
 */
export default function ProjectTimeline({
  stages,
  currentStage,
  stageDates,
}: ProjectTimelineProps) {
  console.log('[Timeline debug]', { currentStage, stageDates });

  const stageKeys = stages.map(s => s.key);
  type StageStatus = 'completed' | 'active' | 'pending';

  const currentIdx = currentStage ? stageKeys.indexOf(currentStage) : -1;

  // Edge case: If currentStageKey is not found, treat all as pending
  if (currentIdx === -1 && stages.length > 0) { // Only if there are stages to show
    console.warn(`[Timeline] currentStageKey '${currentStage}' not found in stages. Defaulting all to pending.`);
    // No need to set currentIdx to something specific if all are pending by default in status calculation below
  }

  const statuses: Record<ProjectStage, StageStatus> = {} as any;

  stageKeys.forEach((key, idx) => {
    if (currentIdx === -1) { // If currentStageKey not found, all are pending
      statuses[key] = 'pending';
      return;
    }
    if (idx < currentIdx) {
      statuses[key] = 'completed';
    } else if (idx === currentIdx) {
      // Special case: If the very last stage is current AND has a date, treat as completed
      if (key === stages[stages.length - 1].key && stageDates[key]) {
        statuses[key] = 'completed';
      } else {
        statuses[key] = 'active';
      }
    } else {
      statuses[key] = 'pending';
    }
  });

  // D. Colour palette & E. Mapping status → tailwind classes (combined)
  const getVisualProperties = (status: StageStatus): StageVisualProperties => {
    switch (status) {
      case 'completed':
        return {
          dotBg: 'bg-green-600 dark:bg-green-500',
          dotBr: 'border-green-600 dark:border-green-500',
          icon: 'text-white',
          label: 'text-green-600 dark:text-green-500',
          bar: 'bg-green-600 dark:bg-green-500' // 100% opacity implied
        };
      case 'active':
        return {
          dotBg: 'bg-blue-50 dark:bg-opacity-10 dark:bg-blue-400', // Adjusted dark for blue-50 equivalent
          dotBr: 'border-blue-600 dark:border-blue-500',
          icon: 'text-blue-600 dark:text-blue-500',
          label: 'text-blue-600 dark:text-blue-500',
          bar: 'bg-blue-600 dark:bg-blue-500' // 100% opacity implied
        };
      case 'pending':
      default:
        return {
          dotBg: 'bg-gray-200 dark:bg-gray-700', // Adjusted from spec for better dark bg
          dotBr: 'border-gray-400 dark:border-gray-600',
          icon: 'text-gray-500 dark:text-gray-400',
          label: 'text-gray-500 dark:text-gray-400',
          bar: 'bg-gray-400 dark:bg-gray-600 opacity-50' // 50% opacity as per spec
        };
    }
  };

  if (!stages || stages.length === 0) {
    return null; // Or some placeholder if no stages
  }

  return (
    <div className="w-full">
      {/* Mobile Layout (screens < md) */}
      <div className="md:hidden flex flex-col items-center space-y-2"> {/* Added space-y for mobile items */}
        {stages.map((stage, idx) => {
          const StageIcon = stage.icon;
          const status = statuses[stage.key];
          const visualProps = getVisualProperties(status);
          const isLast = idx === stages.length - 1;

          return (
            <React.Fragment key={stage.key + '-mobile'}>
              <div className="flex flex-col items-center text-center">
                {/* Dot */}
                <span
                  className={clsx(
                    "flex shrink-0 items-center justify-center rounded-full border-2 transition z-10",
                    "w-10 h-10", // Mobile specific size for dot
                    visualProps.dotBg, visualProps.dotBr
                  )}
                >
                  <StageIcon
                    className={clsx("w-5 h-5", visualProps.icon)} // Mobile specific size for icon
                    strokeWidth={2}
                  />
                </span>
                {/* Label */}
                <span className={clsx("mt-2 font-medium text-xs leading-tight", visualProps.label)}>
                  {stage.label}
                </span>
                {/* Date */}
                {stageDates[stage.key] && (
                  <span className={clsx("mt-1 text-[11px]", getVisualProperties('pending').label)}>
                    {format(parseISO(stageDates[stage.key] as string), "MMM d, yyyy")}
                  </span>
                )}
              </div>
              {/* Vertical Connector Line (Mobile) */}
              {!isLast && (
                <div className={clsx("w-0.5 h-8 my-1", visualProps.bar)} /> // my-1 for spacing, h-8 for length
              )}
            </React.Fragment>
          );
        })}
      </div>

      {/* Desktop Layout (screens >= md) */}
      <div className="hidden md:flex items-center justify-between w-full">
        {stages.map((stage, idx) => {
          const StageIcon = stage.icon;
          const status = statuses[stage.key];
          const visualProps = getVisualProperties(status);
          const isLast = idx === stages.length - 1;

          return (
            <React.Fragment key={stage.key + '-desktop'}>
              <div className="flex flex-col items-center text-center px-1"> {/* px-1 for some spacing of stage content*/}
                {/* Dot */}
                <span
                  className={clsx(
                    "flex shrink-0 items-center justify-center rounded-full border-2 transition z-10",
                    "w-12 h-12", // Desktop specific size for dot
                    visualProps.dotBg, visualProps.dotBr
                  )}
                >
                  <StageIcon
                    className={clsx("w-6 h-6", visualProps.icon)} // Desktop specific size for icon
                    strokeWidth={2}
                  />
                </span>
                {/* Label */}
                <span className={clsx("mt-2 font-medium text-sm leading-tight", visualProps.label)}>
                  {stage.label}
                </span>
                {/* Date */}
                {stageDates[stage.key] && (
                  <span className={clsx("mt-1 text-xs", getVisualProperties('pending').label)}>
                    {format(parseISO(stageDates[stage.key] as string), "MMM d, yyyy")}
                  </span>
                )}
              </div>
              {/* Horizontal Bar (Desktop) */}
              {!isLast && (
                 // flex-1 will make bar take up space. mx-2 provides space around the bar itself.
                <div className={clsx("flex-1 h-1 mx-1", visualProps.bar)} /> 
              )}
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React from 'react';

interface RadioGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onChange' | 'value'> {
  value?: string;
  onValueChange?: (value: string) => void;
  className?: string;
}

interface RadioItemProps {
  value: string;
  checked?: boolean;
  onChange?: () => void;
}

export const RadioGroup = React.forwardRef<HTMLDivElement, RadioGroupProps>(
  ({ className = '', value, onValueChange, children, ...props }, ref) => {
    const handleRadioChange = (childValue: string) => {
      if (onValueChange) {
        onValueChange(childValue);
      }
    };

    // Clone children and pass down props
    const enhancedChildren = React.Children.map(children, child => {
      if (React.isValidElement(child)) {
        return React.cloneElement(child, {
          checked: value === child.props.value,
          onChange: () => handleRadioChange(child.props.value),
        } as RadioItemProps);
      }
      return child;
    });

    return (
      <div
        className={`space-y-2 ${className}`}
        ref={ref}
        role="radiogroup"
        {...props}
      >
        {enhancedChildren}
      </div>
    );
  }
);

interface RadioGroupItemProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange'> {
  value: string;
  className?: string;
  checked?: boolean;
  onChange?: () => void;
}

export const RadioGroupItem = React.forwardRef<HTMLInputElement, RadioGroupItemProps>(
  ({ className = '', id, value, checked, onChange, ...props }, ref) => {
    return (
      <div className="flex items-center">
        <input
          type="radio"
          className={`h-4 w-4 border-gray-300 text-blue-600 focus:ring-blue-500 ${className}`}
          id={id || `radio-${value}`}
          value={value}
          checked={checked}
          onChange={onChange}
          ref={ref}
          {...props}
        />
        {checked && (
          <div className="absolute h-2 w-2 rounded-full bg-blue-600" style={{ left: '0.5rem', top: '0.5rem' }} />
        )}
      </div>
    );
  }
);

RadioGroup.displayName = 'RadioGroup';
RadioGroupItem.displayName = 'RadioGroupItem';

/**
 * Auth API Module
 * 
 * Contains all API functions related to authentication and user management
 */

import { 
  LoginCredentials, 
  RegisterData, 
  ResetPasswordRequest,
  User,
  AuthResult,
  UserRole
} from '../types';

// Import Supabase client from the lib module
import supabase from '@/lib/api/client';
// Import Supabase Session type
import type { Session as SupabaseSession } from '@supabase/supabase-js';

// Import session timeout utilities
import { applySessionTimeout } from '../../../lib/supabase/auth-timeout';

// Simple cache for session data to prevent excessive API calls
interface SessionCache {
  session: SupabaseSession | null;
  timestamp: number;
  expiresAt: number;
}

let sessionCache: SessionCache | null = null;
const CACHE_TTL = 60000; // Cache session for 1 minute

/**
 * Login user with email and password
 */
export async function login(
  credentials: LoginCredentials, 
  onSuccess?: (session: SupabaseSession, user: User) => void
): Promise<AuthResult> {
  try {
    // Use the default client for login
    const { data, error } = await supabase.auth.signInWithPassword({
      email: credentials.email,
      password: credentials.password,
    });

    if (error) {
      console.error('Login error:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Login failed'
      };
    }

    if (!data.user) {
      return {
        success: false,
        error: 'User data not available'
      };
    }

    // Extract role from user metadata
    const role = data.user.user_metadata?.role || 'client';

    // Apply role-specific session timeout
    await applySessionTimeout(
      data.session.access_token,
      data.session.refresh_token,
      role
    );

    // Update the session cache
    sessionCache = {
      session: data.session,
      timestamp: Date.now(),
      expiresAt: data.session.expires_at ? data.session.expires_at * 1000 : Date.now() + (24 * 60 * 60 * 1000)
    };

    const user: User = {
      id: data.user.id,
      email: data.user.email || '',
      role,
      full_name: data.user.user_metadata?.full_name,
      avatar_url: data.user.user_metadata?.avatar_url,
      metadata: data.user.user_metadata
    };

    // Immediately update auth state if callback provided
    if (onSuccess && data.session) {
      onSuccess(data.session, user);
    }

    return {
      success: true,
      user,
      session: data.session
    };
  } catch (error) {
    console.error('Login error:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'An unexpected error occurred'
    };
  }
}

/**
 * Register a new user
 */
export async function register(data: RegisterData): Promise<AuthResult> {
  try {
    // Use the default client for registration
    const { data: authData, error } = await supabase.auth.signUp({
      email: data.email,
      password: data.password,
      options: {
        data: {
          full_name: data.full_name,
          company: data.company,
          role: 'client' // Default role for new users
        }
      }
    });

    if (error) {
      console.error('Registration error:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'An unexpected error occurred'
      };
    }

    if (!authData.user) {
      return {
        success: false,
        error: 'User registration failed'
      };
    }

    const user: User = {
      id: authData.user.id,
      email: authData.user.email || '',
      role: 'client',
      full_name: data.full_name,
      metadata: authData.user.user_metadata
    };

    return {
      success: true,
      user,
      message: 'Registration successful. Please check your email to confirm your account.'
    };
  } catch (error) {
    console.error('Registration error:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'An unexpected error occurred'
    };
  }
}

/**
 * Logout current user
 */
export async function logout(): Promise<AuthResult> {
  try {
    // Perform signOut which should clear the session server-side
    const { error } = await supabase.auth.signOut();

    if (error) {
      console.error('Logout error:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'An unexpected error occurred during logout'
      };
    }

    // Clear the session cache
    sessionCache = null;

    // Additional client-side cleanup to ensure complete logout
    // Clear any Supabase-related items from localStorage
    if (typeof window !== 'undefined') {
      try {
        // Get all keys from localStorage
        const localStorageKeys = Object.keys(localStorage);

        // Filter for Supabase-related keys
        const supabaseKeys = localStorageKeys.filter(key => 
          key.includes('supabase') || key.includes('sb-')
        );

        // Remove all Supabase-related items
        supabaseKeys.forEach(key => localStorage.removeItem(key));

        console.log(`Cleared ${supabaseKeys.length} Supabase-related items from localStorage`);
      } catch (e) {
        console.error('Error clearing localStorage:', e);
      }
    }

    // Force refresh cookies using a direct fetch to the auth endpoint
    try {
      await fetch('/api/auth/logout', { 
        method: 'POST',
        credentials: 'include'
      });
    } catch (e) {
      console.error('Error calling logout endpoint:', e);
    }

    return {
      success: true,
      message: 'Logged out successfully'
    };
  } catch (error) {
    console.error('Logout error:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'An unexpected error occurred during logout'
    };
  }
}

/**
 * Request password reset for user
 */
export async function resetPassword(request: ResetPasswordRequest): Promise<AuthResult> {
  try {
    // --- Use a consistent, production-oriented redirect URL ---
    // Ensure this URL is whitelisted in your Supabase project's redirect URL settings.
    const productionRedirectTo = 'https://portal.drasticdigital.com/update-password';
    // For local development, you might want to use a different URL or make this configurable via env vars.
    // For now, we prioritize the production URL that worked with curl.
    // const redirectTo = process.env.NODE_ENV === 'development' 
    //   ? `http://localhost:3000/update-password` 
    //   : productionRedirectTo;

    const { error } = await supabase.auth.resetPasswordForEmail(request.email, {
      redirectTo: productionRedirectTo, 
    });

    if (error) {
      console.error('Password reset error:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to send password reset email'
      };
    }

    return {
      success: true,
      message: 'Password reset instructions sent to your email'
    };
  } catch (error) {
    console.error('Password reset error:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to send password reset email'
    };
  }
}

/**
 * Update user password
 */
export async function updatePassword(password: string): Promise<AuthResult> {
  try {
    const { data, error } = await supabase.auth.updateUser({
      password
    });

    if (error) {
      return {
        success: false,
        error: error.message
      };
    }

    if (!data.user) {
      return {
        success: false,
        error: 'User data not available'
      };
    }

    return {
      success: true,
      message: 'Password updated successfully'
    };
  } catch (error) {
    console.error('Update password error:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to update password'
    };
  }
}

/**
 * Update user profile
 */
export async function updateProfile(profile: Partial<User>): Promise<AuthResult> {
  try {
    const { data, error } = await supabase.auth.updateUser({
      data: {
        full_name: profile.full_name,
        avatar_url: profile.avatar_url
      }
    });

    if (error) {
      console.error('Update profile error:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to update profile'
      };
    }

    if (!data.user) {
      return {
        success: false,
        error: 'User data not available after update'
      };
    }

    // If a role was explicitly part of the profile update, sync it to the 'profiles' table.
    // This is a minimal sync. Other 'profiles' fields are typically managed by client-api.ts functions.
    if (profile.role) {
      const { error: profileTableError } = await supabase
        .from('profiles')
        .update({ 
            role: profile.role,
            updated_at: new Date().toISOString()
         })
        .eq('id', data.user.id);

      if (profileTableError) {
        console.error("Error syncing role to 'profiles' table in auth/api/updateProfile:", profileTableError);
        // Not necessarily a fatal error for the auth update itself, but good to log.
      }
    }

    const updatedLocalUser: User = {
        id: data.user.id,
        email: data.user.email || '',
        role: (data.user.user_metadata?.role || data.user.app_metadata?.role || 'client') as UserRole,
        full_name: data.user.user_metadata?.full_name || undefined,
        avatar_url: data.user.user_metadata?.avatar_url || undefined,
        metadata: { ...data.user.app_metadata, ...data.user.user_metadata },
    };

    return {
      success: true,
      message: 'Profile updated successfully',
      user: updatedLocalUser // Return the mapped updated auth user
    };
  } catch (error) {
    console.error('Update profile error:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to update profile'
    };
  }
}

/**
 * Get current session
 */
export async function getCurrentSession() {
  try {
    // Check cache first to avoid unnecessary API calls
    const now = Date.now();

    if (sessionCache && 
        sessionCache.timestamp + CACHE_TTL > now && 
        sessionCache.expiresAt > now) {
      return {
        success: true,
        session: sessionCache.session
      };
    }

    // If no valid cache, make the API call
    const { data, error } = await supabase.auth.getSession();

    if (error) {
      // Clear cache on error
      sessionCache = null;
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown session error'
      };
    }

    // Update cache with fresh data
    if (data.session) {
      sessionCache = {
        session: data.session,
        timestamp: now,
        expiresAt: data.session.expires_at ? data.session.expires_at * 1000 : now + (24 * 60 * 60 * 1000)
      };
    } else {
      // No session = logged out
      sessionCache = null;
    }

    return {
      success: true,
      session: data.session
    };
  } catch (error) {
    console.error('Get session error:', error);
    // Clear cache on error
    sessionCache = null;
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown session error'
    };
  }
}

