/**
 * Add a member to a project
 */
export async function addProjectMember(
  projectId: string, 
  email: string, 
  role: string
): Promise<ProjectResult> {
  try {
    // Get the current user ID
    const { data: sessionData } = await supabase.auth.getSession();
    const userId = sessionData?.session?.user?.id;

    if (!userId) {
      return {
        success: false,
        error: 'User not authenticated'
      };
    }

    // First check if the user has permission
    const { data: projectData, error: fetchError } = await supabase
      .from('projects')
      .select('client_id')
      .eq('id', projectId)
      .limit(1)
      .single();

    if (fetchError || !projectData) {
      return {
        success: false,
        error: 'Project not found'
      };
    }

    // Only allow owners to add members
    if (projectData.client_id !== userId) {
      return {
        success: false,
        error: 'You do not have permission to add members to this project'
      };
    }

    // Get the user ID from the email
    const { data: userData, error: userError } = await supabase
      .from('users')
      .select('id')
      .eq('email', email)
      .limit(1)
      .single();

    if (userError || !userData) {
      return {
        success: false,
        error: 'User not found'
      };
    }

    // Add the member
    const { error } = await supabase
      .from('project_members')
      .insert({
        project_id: projectId,
        user_id: userData.id,
        role,
        added_at: new Date().toISOString()
      });

    if (error) {
      return {
        success: false,
        error: error.message
      };
    }

    return {
      success: true
    };
  } catch (error) {
    console.error('Error adding project member:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to add project member'
    };
  }
}

/**
 * Remove a member from a project
 */
export async function removeProjectMember(
  projectId: string, 
  userId: string
): Promise<ProjectResult> {
  try {
    // Get the current user ID
    const { data: sessionData } = await supabase.auth.getSession();
    const currentUserId = sessionData?.session?.user?.id;

    if (!currentUserId) {
      return {
        success: false,
        error: 'User not authenticated'
      };
    }

    // First check if the user has permission
    const { data: projectData, error: fetchError } = await supabase
      .from('projects')
      .select('client_id')
      .eq('id', projectId)
      .limit(1)
      .single();

    if (fetchError || !projectData) {
      return {
        success: false,
        error: 'Project not found'
      };
    }

    // Only allow owners to remove members (or users to remove themselves)
    if (projectData.client_id !== currentUserId && userId !== currentUserId) {
      return {
        success: false,
        error: 'You do not have permission to remove this member'
      };
    }

    // Remove the member
    const { error } = await supabase
      .from('project_members')
      .delete()
      .eq('project_id', projectId)
      .eq('user_id', userId);

    if (error) {
      return {
        success: false,
        error: error.message
      };
    }

    return {
      success: true
    };
  } catch (error) {
    console.error('Error removing project member:', error);
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to remove project member'
    };
  }
}

